import sys

def search(nums, target):
    l, r = 0, len(nums) - 1
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            l = mid + 1
        else:
            r = mid - 1
    return -1

def main():
    data = sys.stdin.read().split()
    if not data: return
    n, target = int(data[0]), int(data[1])
    nums = [int(x) for x in data[2:2+n]]
    print(search(nums, target))

if __name__ == '__main__':
    main()

